import { useState } from "react";
import { Text, View } from "react-native";
import { IconButton, useTheme } from "minerva-design/native";
export default function Basic() {
  const [count, setCount] = useState(0);
  const { colors } = useTheme();
  return (
    <View
      style={{
        flexDirection: "row",
        alignItems: "center",
        flexWrap: "wrap",
        gap: 12,
      }}
    >
      <IconButton
        label="Add"
        onPress={() => setCount((n) => n + 1)}
        icon={(color, size) => <Text style={{ color, fontSize: size }}>+</Text>}
      />
      <IconButton
        label="Settings"
        icon={(color, size) => <Text style={{ color, fontSize: size }}>⚙</Text>}
      />
      <IconButton
        label="Delete"
        icon={(color, size) => <Text style={{ color, fontSize: size }}>⌫</Text>}
      />
      <Text role="status" style={{ color: colors["text-color"] }}>
        {count === 0 ? "Nothing added yet" : `Added ${count} item(s)`}
      </Text>
    </View>
  );
}

import { useState } from "react";
import { Text, View } from "react-native";
import { IconButton, useTheme } from "minerva-design/native";
export default function Toggle() {
  const [liked, setLiked] = useState(false);
  const { colors } = useTheme();
  return (
    <View
      style={{
        flexDirection: "row",
        alignItems: "center",
        flexWrap: "wrap",
        gap: 12,
      }}
    >
      <IconButton
        label="Like"
        color="danger"
        pressed={liked}
        onPressedChange={setLiked}
        icon={(color, size) => <Text style={{ color, fontSize: size }}>♥</Text>}
      />
      <Text style={{ color: colors["text-color"] }}>
        {liked ? "Liked" : "Not liked yet"}
      </Text>
      <IconButton
        label="Bookmark"
        defaultPressed
        icon={(color, size) => <Text style={{ color, fontSize: size }}>◆</Text>}
      />
      <IconButton
        label="Mute"
        shape="square"
        defaultPressed={false}
        icon={(color, size) => <Text style={{ color, fontSize: size }}>♩</Text>}
      />
    </View>
  );
}

import { Text, View } from "react-native";
import { IconButton } from "minerva-design/native";

const VARIANTS = ["ghost", "outline", "solid"] as const;
const SIZES = ["xsmall", "small", "medium", "large"] as const;

const star = (color: string, size: number) => (
  <Text style={{ color, fontSize: size }}>★</Text>
);

export default function VariantsSizes() {
  return (
    <View style={{ gap: 16 }}>
      {VARIANTS.map((variant) => (
        <View key={variant} style={{ flexDirection: "row", gap: 12 }}>
          <IconButton label="Rate" variant={variant} icon={star} />
          <IconButton
            label="Rate"
            variant={variant}
            color="primary"
            icon={star}
          />
          <IconButton
            label="Rate"
            variant={variant}
            color="warning"
            shape="square"
            icon={star}
          />
        </View>
      ))}
      <View style={{ flexDirection: "row", alignItems: "center", gap: 12 }}>
        {SIZES.map((size) => (
          <IconButton
            key={size}
            label={`Favorite (${size})`}
            size={size}
            variant="solid"
            color="primary"
            icon={star}
          />
        ))}
      </View>
    </View>
  );
}
